from pathlib import Path
import os, json, pickle
import numpy as np
base = Path('/app/data')
files = sorted([p for p in base.rglob('*') if p.is_file()])
print('TOTAL_FILES', len(files))
for p in files[:200]:
    print(p)
print('\nREPRESENTATIVE FILE INSPECTION')
for p in files:
    suf = p.suffix.lower()
    if suf == '.npy':
        try:
            arr = np.load(p, allow_pickle=True)
            shape = getattr(arr, 'shape', None)
            dtype = getattr(arr, 'dtype', None)
            print('NPY', p, 'shape=', shape, 'dtype=', dtype)
        except Exception as e:
            print('NPY_ERR', p, e)
    elif suf in {'.json', '.txt', '.csv'}:
        try:
            txt = p.read_text(errors='ignore')
            print(suf.upper(), p, 'HEAD=', txt[:300].replace('\n',' | '))
        except Exception as e:
            print('TXT_ERR', p, e)
    elif suf in {'.pkl', '.pickle'}:
        try:
            obj = pickle.load(open(p,'rb'))
            print('PKL', p, type(obj))
        except Exception as e:
            print('PKL_ERR', p, e)
